def alcance(pos, nivel, mapa):
    casas = {pos}
    for dx, dy in DIR:
        for dist in range(1, 2 * nivel):
            x, y = pos[0] + dx * dist, pos[1] + dy * dist
            if not (0 <= y < len(mapa) and 0 <= x < len(mapa[0])) or mapa[y][x] == 2:
                break
            casas.add((x, y))
            if mapa[y][x] == 1:
                break
    return casas

def prever(mapa, bombas):
    registros = []
    for b in bombas:
        if b.explodida:
            if b.tempo_fogo > 0:
                registros.append([b, set(b.fogo), 0.0])
        else:
            registros.append([b, alcance((b.x, b.y), b.nivel, mapa), max(0.0, b.tempo_explosao)])
    mudou = True
    while mudou:
        mudou = False
        for _, casas, tempo in registros:
            for outro in registros:
                b = outro[0]
                if not b.explodida and (b.x, b.y) in casas and outro[2] > tempo:
                    outro[2] = tempo
                    mudou = True
    prazos, ocupadas = {}, set()
    for b, casas, tempo in registros:
        if not b.explodida:
            ocupadas.add((b.x, b.y))
        for casa in casas:
            prazos[casa] = min(prazos.get(casa, float("inf")), tempo)
    return prazos, ocupadas

def livre(pos, mapa, ocupadas):
    x, y = pos
    return (0 <= y < len(mapa) and 0 <= x < len(mapa[0])
            and mapa[y][x] in (0, 3, 4) and pos not in ocupadas)

def refugio(inicio, mapa, prazos, ocupadas, passo, atraso=0.0):
    fila = deque([(inicio, [], atraso)])
    vistos = {inicio}
    while fila:
        pos, caminho, tempo = fila.popleft()
        if pos not in prazos:
            return caminho
        if tempo + MARGEM >= prazos[pos]:
            continue
        for a, (dx, dy) in enumerate(DIR):
            prox = (pos[0] + dx, pos[1] + dy)
            chegada = tempo + passo
            if prox in vistos or not livre(prox, mapa, ocupadas):
                continue
            if chegada + MARGEM >= prazos.get(prox, float("inf")):
                continue
            vistos.add(prox)
            fila.append((prox, caminho + [a], chegada))
    return None

def bomba_segura(
    pos,
    player,
    mapa,
    bombas,
    hud,
    planejando=False
):
    capacidade_cheia = (
        len(player.bombas) >= player.max_bombas
    )

    bombas_consideradas = list(bombas)

    if capacidade_cheia:
        if not planejando:
            return False

        # Só permite planejar a liberação de capacidade
        # se houver bombas próprias ainda em andamento.
        if not player.bombas:
            return False

        # Para avaliar a posição FUTURA, considera que
        # as bombas próprias já terão terminado.
        ids_proprias = {
            id(bomba)
            for bomba in player.bombas
        }

        bombas_consideradas = [
            bomba
            for bomba in bombas
            if id(bomba) not in ids_proprias
        ]

    prazos, ocupadas = prever(
        mapa,
        bombas_consideradas
    )

    if pos in prazos or pos in ocupadas:
        return False

    virtual = SimpleNamespace(
        x=pos[0],
        y=pos[1],
        nivel=player.bomba_nivel,
        explodida=False,
        tempo_explosao=hud.get(
            "tempo_explosao",
            4.0
        ),
    )

    previstos, bloqueadas = prever(
        mapa,
        bombas_consideradas + [virtual]
    )

    passo = max(
        INTERVALO,
        hud.get("tempo_movimento", 0.1) + 0.04
    )

    caminho = refugio(
        pos,
        mapa,
        previstos,
        bloqueadas,
        passo,
        passo
    )

    return caminho is not None and len(caminho) > 0

def distancias(mapa, inimigos):
    from heapq import heappop, heappush
    dist, fila = {}, []
    for p in inimigos:
        casa = (p.grid_x, p.grid_y)
        dist[casa] = 0
        heappush(fila, (0, casa))
    while fila:
        custo, casa = heappop(fila)
        if custo != dist[casa]:
            continue
        for dx, dy in DIR:
            proxima = (casa[0]+dx, casa[1]+dy)
            x, y = proxima
            if not (0 <= y < len(mapa) and 0 <= x < len(mapa[0])) or mapa[y][x] == 2:
                continue
            novo = custo + (6 if mapa[y][x] == 1 else 1)
            if novo < dist.get(proxima, float("inf")):
                dist[proxima] = novo
                heappush(fila, (novo, proxima))
    return dist


def opcoes(player, mapa, jogadores, bombas, tempo_restante, hud):
    pos = (player.grid_x, player.grid_y)
    passo = max(INTERVALO, hud.get("tempo_movimento", 0.1)+0.04)
    prazos, ocupadas = prever(mapa, bombas)
    inimigos = [p for p in jogadores if p is not player and p.ativo]
    dist = distancias(mapa, inimigos)
    terrenos, riscos, movimentos, seguros = [], [], [], []
    for casa in [pos]+[(pos[0]+dx,pos[1]+dy) for dx,dy in DIR]:
        t = prazos.get(casa)
        riscos.append(0 if t is None else (3 if t <= 0 else (2 if t < 1 else 1)))
    for a,(dx,dy) in enumerate(DIR):
        casa = (pos[0]+dx,pos[1]+dy)
        x,y = casa
        terreno = mapa[y][x] if 0 <= y < len(mapa) and 0 <= x < len(mapa[0]) else 2
        terrenos.append(5 if casa in ocupadas else terreno)
        if livre(casa,mapa,ocupadas):
            movimentos.append(a)
            if (passo+MARGEM < prazos.get(casa,float("inf"))
                    and refugio(casa,mapa,prazos,ocupadas,passo,passo) is not None):
                seguros.append(a)
    alternativas = {}
    if pos in prazos:
        caminho = refugio(pos,mapa,prazos,ocupadas,passo)
        if caminho:
            a = caminho[0]
        elif seguros:
            a = seguros[0]
        elif movimentos:
            a = max(movimentos,key=lambda i:prazos.get((pos[0]+DIR[i][0],pos[1]+DIR[i][1]),float("inf")))
        else:
            a = 5
        alternativas[5] = (a, 2.0)
    else:
        fila, vistos, casas = deque([(pos,[])]), {pos}, []
        while fila:
            casa,caminho = fila.popleft()
            casas.append((casa,caminho))
            for a,(dx,dy) in enumerate(DIR):
                proxima = (casa[0]+dx,casa[1]+dy)
                if proxima in vistos or proxima in prazos or not livre(proxima,mapa,ocupadas):
                    continue
                if not caminho and a not in seguros:
                    continue
                vistos.add(proxima)
                fila.append((proxima,caminho+[a]))
        conectado = any((p.grid_x,p.grid_y) in vistos for p in inimigos)
        candidatos = []
        for casa,caminho in casas:
            passos = len(caminho)
            x,y = casa
            if caminho and mapa[y][x] in (3,4):
                util = (mapa[y][x] == 3 and player.max_bombas < hud.get("max_bombas",5)) or (mapa[y][x] == 4 and player.bomba_nivel < 4)
                candidatos.append((0,(8.0 if util else 0.2)-0.65*passos,caminho[0]))
            if caminho and inimigos and dist.get(casa,float("inf")) < dist.get(pos,0):
                ganho = dist[pos]-dist[casa]
                score = (0.9 if conectado else 0.2)*ganho-0.6*passos
                candidatos.append((3,score,caminho[0]))
            alcance_b = alcance(casa,player.bomba_nivel,mapa)
            nb = sum(mapa[fy][fx] == 1 and (fx,fy) not in prazos for fx,fy in alcance_b)
            alvos = [p for p in inimigos if (p.grid_x,p.grid_y) in alcance_b]
            perdas = sum(mapa[fy][fx] in (3,4) for fx,fy in alcance_b)
            if nb or alvos:
                bonus = 0.0
                if nb and not conectado:
                    bonus = sum(max(0,dist.get(casa,0)-dist.get(c,0))*0.5
                                for c in alcance_b if mapa[c[1]][c[0]] == 1 and c not in prazos)
                bruto = nb*(0.8 if conectado else 2.0)+bonus+8*len(alvos)-0.65*passos-0.8*perdas
                candidatos.append((6,bruto,(casa,caminho,alvos)))
        # Avalia no maximo oito locais de bomba por decisao.
        locais = sorted([c for c in candidatos if c[0] == 6], key=lambda c:c[1], reverse=True)[:8]
        candidatos = [c for c in candidatos if c[0] != 6]
        for _,score,(casa,caminho,alvos) in locais:
            if not bomba_segura(casa,player,mapa,bombas,hud,planejando=bool(caminho)):
                continue
            if alvos:
                virtual = SimpleNamespace(x=casa[0],y=casa[1],nivel=player.bomba_nivel,
                                          explodida=False,tempo_explosao=hud.get("tempo_explosao",4.0))
                pp,oo = prever(mapa,list(bombas)+[virtual])
                for inimigo in alvos:
                    fuga = refugio((inimigo.grid_x,inimigo.grid_y),mapa,pp,oo,hud.get("tempo_movimento",0.1))
                    score += 25.0 if fuga is None else min(len(fuga),6)*0.5
            objetivo = 2 if alvos else 1
            acao = caminho[0] if caminho else 4
            candidatos.append((objetivo,score,acao))
        for objetivo,score,acao in candidatos:
            if score > 0 and (objetivo not in alternativas or score > alternativas[objetivo][1]):
                alternativas[objetivo] = (acao,score)
        # Nao oferecer espera gratuita se ha progresso seguro disponivel.
        if not alternativas:
            alternativas[4] = (5,0.0)
    distancia_inimigo = min((abs(pos[0]-p.grid_x)+abs(pos[1]-p.grid_y) for p in inimigos),default=99)
    rumo = 0
    if inimigos:
        alvo = min(inimigos,key=lambda p:abs(pos[0]-p.grid_x)+abs(pos[1]-p.grid_y))
        rumo = (1 if alvo.grid_x>pos[0] else -1 if alvo.grid_x<pos[0] else 0)*3+(1 if alvo.grid_y>pos[1] else -1 if alvo.grid_y<pos[1] else 0)
    estado = json.dumps(terrenos+riscos+[player.bomba_nivel,min(player.max_bombas-len(player.bombas),3),
                         min(distancia_inimigo//3,5),rumo,0 if tempo_restante>90 else 1 if tempo_restante>30 else 2,
                         sorted(alternativas)])
    return estado, alternativas


class Agente:
    def __init__(self, tabela=None, treinando=False, episodios=0, seed=None):
        self.q = tabela if tabela is not None else {}
        self.treinando = treinando
        self.episodios = episodios
        self.rng = random.Random(seed)
        self.anterior = None
        self.ultimo_tempo = None
        self.encerrado = False

    def _linha(self, estado):
        if not self.treinando:
            return self.q.get(estado,[0.0]*len(OBJETIVOS))
        return self.q.setdefault(estado,[0.0]*len(OBJETIVOS))

    def _atualizar(self, recompensa, estado=None, objetivos=None):
        if not self.treinando or self.anterior is None:
            return
        s,a,_ = self.anterior
        futuro = 0.0 if estado is None else max(self._linha(estado)[i] for i in objetivos)
        valores = self._linha(s)
        valores[a] += 0.15*(recompensa+0.95*futuro-valores[a])

    def decidir_acao(self, player, mapa, jogadores, bombas, tempo_restante, pontos, hud_info, self_state):
        if self.encerrado:
            return "parado"
        if self.ultimo_tempo is not None and tempo_restante>self.ultimo_tempo:
            self.anterior,self.ultimo_tempo,self.encerrado = None,None,False
        if self.ultimo_tempo is not None and self.ultimo_tempo-tempo_restante<INTERVALO-1e-6:
            return "parado"
        self.ultimo_tempo = tempo_restante
        estado, alternativas = opcoes(player,mapa,jogadores,bombas,tempo_restante,hud_info)
        indice = next(i for i,p in enumerate(jogadores) if p is player)
        pontuacao = pontos[indice]
        if self.anterior is not None:
            self._atualizar((pontuacao-self.anterior[2])/1000.0,estado,alternativas)
        epsilon = max(0.05,0.25*(0.995**self.episodios)) if self.treinando else 0.0
        if self.rng.random()<epsilon:
            objetivo = self.rng.choice(list(alternativas))
        else:
            # Prior fraco orienta estados novos; Q pode superar essa preferencia.
            valores = self._linha(estado)
            melhor = max(valores[i]+0.02*min(alternativas[i][1],20) for i in alternativas)
            empatados = [i for i in alternativas if abs(valores[i]+0.02*min(alternativas[i][1],20)-melhor)<1e-9]
            objetivo = self.rng.choice(empatados)
        self.anterior = (estado,objetivo,pontuacao)
        return ACOES[alternativas[objetivo][0]]

    def finalizar(self,pontuacao,morreu=False,venceu=False):
        if self.encerrado:
            return
        recompensa = -10.0 if morreu else 10.0 if venceu else 0.0
        if self.anterior is not None:
            recompensa += (pontuacao-self.anterior[2])/1000.0
            self._atualizar(recompensa)
        self.anterior = None
        self.encerrado = True


# Uma instancia por objeto de jogador. Nenhuma chamada externa de finalizacao
# e necessaria para a versao de competicao, que so consulta o modelo.
_instancias = {}

def decidir_acao(player,mapa,jogadores,bombas,tempo_restante,pontos,hud_info,self_state):
    chave = id(player)
    instancia = _instancias.get(chave)
    if instancia is None or (instancia.ultimo_tempo is not None and tempo_restante>instancia.ultimo_tempo):
        instancia = Agente(MODELO_EMBUTIDO,treinando=False)
        _instancias[chave] = instancia
    return instancia.decidir_acao(player,mapa,jogadores,bombas,tempo_restante,pontos,hud_info,self_state)